<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WastedToken Mint | Collectible Challenge Coins</title>
    <style>
        :root {
            --bg: #050505;
            --text: #e0e0e0;
            --accent: #c5a059;
            --gold: #ffd700;
            --silver: #c0c0c0;
            --bronze: #cd7f32;
            --obsidian: #1a1a1a;
            --font-serif: 'Playfair Display', serif, Georgia, 'Times New Roman';
        }

        * { box-sizing: border-box; margin: 0; padding: 0; }
        body {
            background-color: var(--bg);
            color: var(--text);
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
            overflow-x: hidden;
            line-height: 1.6;
        }

        h1, h2, h3 {
            font-family: var(--font-serif);
            text-transform: uppercase;
            letter-spacing: 4px;
            text-align: center;
        }

        /* Hero Section */
        #hero {
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            position: relative;
            overflow: hidden;
            background: radial-gradient(circle at center, #1a1a1a 0%, #050505 100%);
        }

        #coin-hero {
            width: 500px;
            height: 500px;
            max-width: 90vw;
            max-height: 50vh;
            cursor: grab;
        }

        .hero-title {
            position: absolute;
            top: 50px;
            font-size: 2.5rem;
            color: var(--accent);
            text-shadow: 0 0 20px rgba(197, 160, 89, 0.4);
        }

        /* About Section */
        #about {
            padding: 100px 20px;
            max-width: 800px;
            margin: 0 auto;
            text-align: center;
        }

        #about h2 { margin-bottom: 30px; font-size: 2.5rem; color: var(--accent); }
        #about p { font-size: 1.2rem; color: #aaa; }

        /* Collection Grid */
        #collection {
            padding: 60px 20px 120px;
            max-width: 1200px;
            margin: 0 auto;
        }

        #collection h2 { margin-bottom: 50px; font-size: 2.5rem; }

        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 30px;
        }

        .edition {
            background: #111;
            border: 1px solid #222;
            padding: 20px;
            text-align: center;
            border-radius: 12px;
            transition: transform 0.3s ease, border-color 0.3s ease;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .edition:hover {
            transform: translateY(-10px);
            border-color: var(--accent);
        }

        .edition-canvas {
            width: 100%;
            aspect-ratio: 1;
            margin-bottom: 20px;
        }

        .edition h3 {
            font-size: 1.4rem;
            margin-bottom: 10px;
        }

        .status {
            font-size: 0.8rem;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 15px;
            display: block;
        }

        .buy {
            background: var(--accent);
            color: #000;
            border: none;
            padding: 12px 24px;
            font-weight: bold;
            text-transform: uppercase;
            cursor: pointer;
            width: 100%;
            border-radius: 4px;
            transition: opacity 0.2s;
        }

        .buy:hover { opacity: 0.9; }
        .buy:disabled {
            background: #333;
            color: #777;
            cursor: not-allowed;
        }

        /* Sold Out & Coming Soon styles */
        [data-state="sold-out"] .status { color: #ff4d4d; }
        [data-state="coming-soon"] .status { color: #aaa; }

        footer {
            text-align: center;
            padding: 40px;
            font-size: 0.8rem;
            color: #444;
            border-top: 1px solid #111;
        }
    </style>
</head>
<body>

    <section id="hero">
        <h1 class="hero-title">WastedToken Mint</h1>
        <canvas id="coin-hero"></canvas>
    </section>

    <section id="about">
        <h2>The Art of Scarcity</h2>
        <p>WastedToken Mint produces elite, physical challenge coins for the digital age. Each piece is a tangible piece of the blockchain, meticulously crafted with metallic precision and heavy-weight texture. No pixels, just pure metal.</p>
    </section>

    <section id="collection">
        <h2>The Editions</h2>
        <div class="grid">
            <div class="edition" data-edition="bronze" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Bronze</h3>
                <span class="status">Available</span>
                <button class="buy">Add to cart</button>
            </div>
            <div class="edition" data-edition="silver" data-state="available">
                <canvas class="edition-canvas"></canvas>
                <h3>Silver</h3>
                <span class="status">Available</span>
                <button class="buy">Add to cart</button>
            </div>
            <div class="edition" data-edition="gold" data-state="sold-out">
                <canvas class="edition-canvas"></canvas>
                <h3>Gold</h3>
                <span class="status">SOLD OUT</span>
            </div>
            <div class="edition" data-edition="black" data-state="coming-soon">
                <canvas class="edition-canvas"></canvas>
                <h3>Obsidian</h3>
                <span class="status">Winter Season</span>
            </div>
        </div>
    </section>

    <footer>
        &copy; <span id="year"></span> WastedToken Mint. All rights reserved.
    </footer>

    <script>
        /** 
         * WEBGL CORE 
         */
        const vs = `
            attribute vec2 position;
            varying vec2 vUv;
            void main() {
                vUv = position * 0.5 + 0.5;
                gl_Position = vec4(position, 0.0, 1.0);
            }
        `;

        const fs = `
            precision highp float;
            varying vec2 vUv;
            uniform float uTime;
            uniform vec3 uColor;
            uniform sampler2D uTextureFront;
            uniform sampler2D uTextureBack;
            uniform vec2 uResolution;

            // SDF Functions
            float sdCylinder(vec3 p, float r, float h) {
                vec2 d = abs(vec2(length(p.xy), p.z)) - vec2(r, h);
                return min(max(d.x, d.y), 0.0);
            }

            float sdCoin(vec3 p) {
                float r = 0.7;
                float h = 0.06;
                // Ridged edge math
                float angle = atan(p.y, p.x);
                float ridge = sin(angle * 60.0) * 0.015 * (1.0 - length(p.xy)/r);
                float r_mod = r + ridge;

                float d_cyl = length(p.xy) - r_mod;
                float d_z = abs(p.z) - h;
                return max(d_cyl, d_z);
            }

            vec3 getNormal(vec3 p) {
                vec2 e = vec2(0.001, 0.0);
                return normalize(vec3(
                    sdCoin(p + e.xyy) - sdCoin(p - e.xyy),
                    sdCoin(p + e.yxy) - sdCoin(p - e.yxy),
                    sdCoin(p + e.yyx) - sdCoin(p - e.yyx)
                ));
            }

            void main() {
                vec2 uv = (gl_FragCoord.xy * 2.0 - uResolution.xy) / min(uResolution.y, uResolution.x);
                vec3 ro = vec3(0.0, 0.0, 2.5); // Camera
                vec3 rd = normalize(vec3(uv, -1.5));

                // Apply rotation
                float ty = uTime * 2.0;
                float tx = uTime * 1.0;

                mat2 ry = mat2(cos(ty), -sin(ty), sin(ty), cos(ty));
                mat2 rx = mat2(cos(tx), -sin(tx), sin(tx), cos(tx));

                // Rotate ray
                rd.xy *= ry;
                rd.yz *= rx;
                ro.yz *= rx;
                ro.xy *= ry;
                // Rotate origin too (though centered, good practice)
                vec3 ro_rot = vec3(0.0,0.0,2.5); 

                // Raymarching
                float t = 0.0;
                float d = 0.0;
                for(int i = 0; i < 60; i++) {
                    p = ro + rd * t;
                    d = sdCoin(p);
                    if(d < 0.001 || t > 10.0) break;
                    t += d;
                }

                vec3 col = vec3(0.03, 0.03, 0.05); // Backdrop

                if(t < 10.0) {
                    vec3 p = ro + rd * t;
                    vec3 n = getNormal(p);
                    vec3 view = -rd;
                    vec3 light = normalize(vec3(2.0, 3.0, 4.0));

                    // Lighting
                    float diff = max(dot(n, light), 0.0);
                    vec3 reflect_vec = reflect(-light, n);
                    float spec = pow(max(dot(view, reflect_vec), 0.0), 32.0);

                    // Material
                    vec3 baseCol = uColor;

                    // Texture mapping
                    vec2 texUv = p.xy * 1.5; // Scale texture

                    if(p.z > 0.04) {
                        // Front Face
                        vec4 tex = texture2D(uTextureFront, texUv * 0.5 + 0.5);
                        baseCol = mix(baseCol, tex.rgb, tex.a);
                    } else if (p.z < -0.04) {
                        // Back Face
                        vec4 tex = texture2D(uTextureBack, texUv * 0.5 + 0.5);
                        baseCol = mix(baseCol, tex.rgb, tex.a);
                    } else {
                        // Edge
                        baseCol = baseCol * 0.8;
                    }

                    col = baseCol * (diff + 0.1) + spec * 0.6;

                    // Simple ambient occlusion / Rim
                    float rim = 1.0 - max(dot(n, view), 0.0);
                    col += pow(rim, 4.0) * 0.2 * baseCol;
                }

                gl_FragColor = vec4(pow(col, vec3(0.4545)), 1.0);
            }
        `;

        const vs_simple = `
            attribute vec2 position;
            varying vec2 vUv;
            void main() { vUv = position * 0.5 + 0.5; gl_Position = vec4(position, 0.0, 1.0); }
        `;

        const fs_simple = `
            precision highp float;
            varying vec2 vUv;
            uniform vec3 uColor;
            uniform float uTime;
            uniform sampler2D uTextureFront;
            uniform sampler2D uTextureBack;
            void main() {
                // Just a simple static/slowly spinning render for the grid to keep performance high
                // But we'll use the same logic for consistency
                gl_FragColor = vec4(uColor, 1.0); 
            }
        `;

        /** 
         * ENGINE 
         */
        class CoinRenderer {
            constructor(canvas, color, isHero = false) {
                this.canvas = canvas;
                this.gl = canvas.getContext('webgl');
                this.color = color;
                this.isHero = isHero;
                this.t = 0;
                this.init();
            }

            init() {
                const gl = this.gl;
                // Compile shaders
                const createShader = (gl, type, source) => {
                    const s = gl.createShader(type);
                    gl.shaderSource(s, source);
                    gl.compileShader(s);
                    return s;
                };

                this.program = gl.createProgram();
                gl.attachShader(this.program, createShader(gl, gl.VERTEX_SHADER, this.isHero ? vs : vs_simple));
                gl.attachShader(this.program, createShader(gl, gl.FRAGMENT_SHADER, this.isHero ? fs : fs_simple));
                gl.linkProgram(this.program);
                gl.useProgram(this.program);

                // Geometry
                const vertices = new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]);
                const buffer = gl.createBuffer();
                gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
                gl.bufferData(gl.ARRAY_BUFFER, vertices, gl.STATIC_DRAW);

                const posLoc = gl.getAttribLocation(this.program, 'position');
                gl.enableVertexAttribArray(posLoc);
                gl.vertexAttribPointer(posLoc, 2, gl.FLOAT, false, 0, 0);

                this.uTimeLoc = gl.getUniformLocation(this.program, 'uTime');
                this.uResLoc = gl.getUniformLocation(this.program, 'uResolution');
                this.uColLoc = gl.getUniformLocation(this.program, 'uColor');

                // Texture setup
                this.texFront = this.createTextureFromCanvas(this.emblemCanvas);
                this.texBack = this.createTextureFromCanvas(this.textCanvas);
            }

            createTextureFromCanvas(sourceCanvas) {
                const gl = this.gl;
                const tex = gl.createTexture();
                gl.bindTexture(gl.TEXTURE_2D, tex);
                gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, sourceCanvas);
                gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
                gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
                gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
                return tex;
            }

            createTextureFromCanvas(sourceCanvas) {
                const gl = this.gl;
                const tex = gl.createTexture();
                gl.bindTexture(gl.TEXTURE_2D, tex);
                // Ensure we can sample textures correctly
                gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, sourceCanvas);
                gl.generateMipmap(gl.TEXTURE_2D);
                return tex;
            }

            // Manual texture generation to avoid async/external issues
            async prepareAssets(emblemCtx, textCtx) {
                this.emblemCanvas = this.makeCanvas(512, 512);
                this.textCanvas = this.makeCanvas(512, 512);

                this.drawEmblem(this.emblemCanvas.getContext('2d'));
                this.drawText(this.textCanvas.getContext('2d'));
            }

            makeCanvas(w, h) {
                const c = document.createElement('canvas');
                c.width = w; c.height = h;
                return c;
            }

            drawEmblem(ctx) {
                ctx.fillStyle = 'black';
                ctx.fillRect(0,0,512,512);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = 'bold 240px serif';
                ctx.fillText('W', 256, 256);
                // Add a simple ring/star effect
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 10;
                ctx.beginPath();
                ctx.arc(256, 256, 220, 0, Math.PI*2);
                ctx.stroke();
            }

            drawText(ctx) {
                ctx.fillStyle = 'black';
                ctx.fillRect(0,0,512,512);
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = 'bold 50px serif';
                ctx.fillText('10,000', 256, 240);
                ctx.font = '30px serif';
                ctx.fillText('TOKENS', 256, 310);
            }

            render(t) {
                const gl = this.gl;
                gl.viewport(0, 0, this.canvas.width, this.canvas.height);
                gl.clear(gl.COLOR_BUFFER_BIT);
                gl.useProgram(this.program);

                gl.uniform1f(this.uTimeLoc, t);
                gl.uniform3fv(this.uColLoc, this.color);
                gl.uniform2f(this.uResLoc, this.canvas.width, this.canvas.height);

                gl.activeTexture(gl.TEXTURE0);
                gl.bindTexture(gl.TEXTURE_2D, this.texFront);
                gl.uniform1i(gl.getUniformLocation(this.program, 'uTextureFront'), 0);

                gl.activeTexture(gl.TEXTURE1);
                gl.bindTexture(gl.TEXTURE_2D, this.texBack);
                gl.uniform1i(gl.getUniformLocation(this.program, 'uTextureBack'), 1);

                gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
            }
        }

        /** 
         * MAIN APP LOGIC 
         */
        let heroRenderer, animId;
        let time = 0;
        let isPaused = false;

        async function initApp() {
            document.getElementById('year').textContent = new Date().getFullYear();

            // 1. Create shared assets via dummy canvas first to satisfy dependencies
            const dummy = document.createElement('canvas');
            const ctx = dummy.getContext('2d');
            dummy.width = 512; dummy.height = 512;

            // 2. Initialize Hero
            const heroCanvas = document.getElementById('coin-hero');
            heroCanvas.width = 500;
            heroCanvas.height = 500;
            heroRenderer = new CoinRenderer(heroCanvas, [0.8, 0.6, 0.3]); // Bronze default
            await heroRenderer.prepareAssets();

            // 3. Initialize Grid (simplified versions)
            const editions = document.querySelectorAll('.edition');
            const colors = {
                bronze: [0.8, 0.5, 0.3],
                silver: [0.9, 0.9, 0.9],
                gold: [1.0, 0.85, 0.4],
                black: [0.1, 0.1, 0.1]
            };

            for (const el of editions) {
                const type = el.dataset.edition;
                const canvas = el.querySelector('canvas');
                canvas.width = 256;
                canvas.height = 256;
                // We'll use a lighter version of the same renderer for the grid
                // For performance and simplicity in this one-pass, we'll just use a 
                // simplified WebGL or even 2D context to show the color. 
                // But let's try a second renderer for the "impressive" part.
                const gridRenderer = new CoinRenderer(canvas, colors[type]);
                gridRenderer.prepareAssets();
                el.dataset.renderer = gridRenderer;
            }

            // 4. Animation Loop
            function loop() {
                if (!isPaused) {
                    time += 0.005;
                    if (time > 1) time = 0; // Loop
                    heroRenderer.render(time);

                    // Update grid renders (static/slowly rotate)
                    for (const el of editions) {
                        const r = el.dataset.renderer;
                        if (r) r.render(time * 0.1);
                    }
                }
                animId = requestAnimationFrame(loop);
            }
            loop();

            // 5. Expose API
            window.demo = {
                canvas: heroCanvas,
                setTime: (t) => {
                    time = t;
                    heroRenderer.render(t);
                },
                pause: () => {
                    isPaused = true;
                }
            };
        }

        window.addEventListener('DOMContentLoaded', initApp);

    </script>
</body>
</html>

